from lib import *
S = SS('f65')
R = J('f65'); rw = R['rows']; st = R['struct']; sl = R['slow']; base = R['base']; b2 = R['base2']
steps = [
    step(f"渲染 1000 行表格,三列输出完全相同、只是第三列(价格文本)的来源不同:预先在 Python 里算好(基线){base:.3f} ms;全局函数 fmt_price(r.price){rw['全局函数 fmt_price(r.price)']:.3f} ms({rw['全局函数 fmt_price(r.price)'] / base:.2f}×);过滤器 r.price|fmt {rw['过滤器 r.price|fmt']:.3f} ms({rw['过滤器 r.price|fmt'] / base:.2f}×);对象方法 r.price_text() {rw['对象方法 r.price_text()']:.3f} ms({rw['对象方法 r.price_text()'] / base:.2f}×)。每行调用一个简单函数约增加 {(rw['全局函数 fmt_price(r.price)'] - base) / 1000 * 1000:.2f} µs。", t=tl(S(1)), done=lidx(S(1), '预先在 Python 里算好', '全局函数 fmt_price', '过滤器 r.price|fmt'), mark=lidx(S(1), '对象方法'), b=bars([['预先算好', base, f'{base:.3f} ms'], ['过滤器', rw['过滤器 r.price|fmt'], f"{rw['过滤器 r.price|fmt']:.3f} ms"], ['全局函数', rw['全局函数 fmt_price(r.price)'], f"{rw['全局函数 fmt_price(r.price)']:.3f} ms"]], rw['全局函数 fmt_price(r.price)'], done=[0, 1, 2]), kv=KV([['预先算好', f'{base:.3f} ms'], ['全局函数', f"{rw['全局函数 fmt_price(r.price)']:.3f} ms"], ['过滤器', f"{rw['过滤器 r.price|fmt']:.3f} ms"]], ['全局函数'])),
    step(f"同样输出的不同结构(每行三个单元格):直接写 {b2:.3f} ms;宏 cell() 每行调用 3 次 {st['macro cell() 每行 3 次调用']:.3f} ms({st['macro cell() 每行 3 次调用'] / b2:.2f}×);每行 include 一个模板 {st['每行 include 一个模板']:.3f} ms({st['每行 include 一个模板'] / b2:.2f}×)。宏与 include 比单个函数调用更贵,因为每次要建立新的上下文。", t=tl(S(2)), done=lidx(S(2), '直接写'), mark=lidx(S(2), 'macro cell()', '每行 include'), kv=KV([['直接写', f'{b2:.3f} ms'], ['宏 ×3 每行', f"{st['macro cell() 每行 3 次调用']:.3f} ms"], ['include 每行', f"{st['每行 include 一个模板']:.3f} ms"]], ['宏 ×3 每行'])),
    step(f"成对对比:{{% set p = r.price * 2 %}} 算一次用三次 {R['set'][0]:.3f} ms;同一个表达式写三遍 {R['set'][1]:.3f} ms,是 set 的 {R['set'][1] / R['set'][0]:.2f} 倍。重复用到的值先 set。", t=tl(S(3)), done=lidx(S(3), 'set:'), kv=KV([['set 一次', f"{R['set'][0]:.3f} ms"], ['写三遍', f"{R['set'][1]:.3f} ms"]], ['写三遍'])),
    step(f"selectattr 与 sort 放在模板里做还是在 Python 里先做:selectattr(price>500)模板里做 {R['select'][0]:.3f} ms,Python 里先过滤再渲染 {R['select'][1]:.3f} ms;sort(price 降序)模板里做 {R['sort'][0]:.3f} ms,Python 里先排序再渲染 {R['sort'][1]:.3f} ms(Python 里的过滤与排序本身各约 0.03 ms,所以整体更省)。", t=tl(S(4)), done=lidx(S(4), 'selectattr(price>500)', 'sort(price 降序)'), kv=KV([['selectattr', f"模板 {R['select'][0]:.3f} ms vs Python 先做 {R['select'][1]:.3f} ms"], ['sort', f"模板 {R['sort'][0]:.3f} ms vs Python 先做 {R['sort'][1]:.3f} ms"]], ['selectattr'])),
    step(f"调用次数:全局函数在模板循环里每行调用一次:渲染 3 行调用 {R['calls3']} 次,渲染 1000 行调用 {R['callsN']} 次。函数里有任何额外开销都会乘以行数。", t=tl(S(5)), done=lidx(S(5), '渲染 3 行', '渲染 1000 行'), kv=KV([['3 行', f"{R['calls3']} 次"], ['1000 行', f"{R['callsN']} 次"]], ['1000 行'])),
    step(f"慢函数的后果:函数里放 0.1 ms 的等待(模拟一次缓存或数据库往返),渲染 200 行:不调用慢函数 {sl[0]:.3f} ms;每行调用一次 {sl[1]:.2f} ms(约 {sl[1] / sl[0]:.0f} 倍,200 次 sleep 本身约 31 ms)。模板里调用的函数要保证是纯计算,需要 IO 的数据在视图里一次取好再传进来。", t=tl(S(6)), b=bars([['不调用慢函数', sl[0], f'{sl[0]:.3f} ms'], ['每行调用慢函数', sl[1], f'{sl[1]:.2f} ms']], sl[1], done=[0, 1]), kv=KV([['不调用', f'{sl[0]:.3f} ms'], ['每行调用一次慢函数', f'{sl[1]:.2f} ms'], ['倍数', f'≈{sl[1] / sl[0]:.0f}']], ['倍数'])),
]
A = mkartf('f65', 65, 'Flask,Jinja2,模板性能,函数调用,真实验证,动画演示',
    f'实测模板里执行函数的代价(1000 行表格):全局函数约 {rw["全局函数 fmt_price(r.price)"] / base:.2f}×、过滤器约 {rw["过滤器 r.price|fmt"] / base:.2f}×;宏与 include 比直接写贵 {st["macro cell() 每行 3 次调用"] / b2:.1f}×、{st["每行 include 一个模板"] / b2:.1f}×;set 复用比重复表达式快 {R["set"][1] / R["set"][0]:.2f}×;模板里放 0.1 ms 的慢函数会让 200 行渲染慢约 {sl[1] / sl[0]:.0f} 倍。',
    '模板里写 {{ fmt(price) }} 有多贵?宏和 include 的代价呢?什么该在模板里算、什么该在视图里先算好?这篇对 1000 行表格做一组苹果对苹果的对比(输出相同,只改写法)。',
    [(f'{sl[1] / sl[0]:.0f}×', '模板里每行调用一个 0.1 ms 慢函数,200 行渲染相对不调用的倍数'), (f'{st["macro cell() 每行 3 次调用"] / b2:.1f}×', '宏(每行 3 次调用)相对直接写的耗时倍数'), (str(R['callsN']), '1000 行循环里全局函数被调用的次数')],
    [('函数调用的代价', '<p>上一篇:<a href="flask-jinja2-bytecode-cache.html">Jinja2 Bytecode Cache</a>;下一篇:<a href="flask-config-load-order.html">Flask Config 加载顺序</a>。宏与 include 的写法见<a href="flask-jinja2-macro.html">Jinja2 宏</a>。</p>'), ('宏与 include', None), ('set 复用', None), ('集合运算的位置', None), ('调用次数', None), ('慢函数', None)],
    steps, [ENV_F + '。每项取 3 组中的最小值,每组渲染 15 次;不同机器的绝对值会不同,看相对关系', '没有验证:更大的数据量(10 万行)下的内存占用与流式渲染、PyPy 或 free-threaded 构建下的差别、模板预编译成 Python 模块的效果、Jinja 的 {% for %} loop 变量的代价(本次实验里不同输出的对照已去掉)'], '模板性能')
